-- Edit a question's answer or explanations only together with a version bump, so it is re-reviewed.
insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('pri-code-001', '"a"'::jsonb, '+ glues "Hi" and "!" together, so the program prints Hi!.', '{"b":"The + joins the two strings; it is not printed itself.","c":"print() shows the text without the quote marks."}'::jsonb, null),
  ('pri-code-002', '"c"'::jsonb, 'x holds 3, so x + 2 is 5.', '{"a":"Without quotes, x + 2 is worked out: 3 + 2.","b":"x holds the number 3, not text, so + adds instead of joining."}'::jsonb, null),
  ('pri-code-003', '"b"'::jsonb, '* multiplies, so 2 * 4 is 8.', '{"c":"* means multiply, not \"write the numbers next to each other\".","a":"Without quotes the sum is worked out before printing."}'::jsonb, null),
  ('pri-code-004', '{"accept":["ababab"]}'::jsonb, '"ab" * 3 repeats the text three times: ababab.', null, null),
  ('pri-code-005', '"true"'::jsonb, '7 - 2 is 5, and print() shows it.', '{"false":"The subtraction happens before printing, giving 5."}'::jsonb, null),
  ('pri-code-006', '"b"'::jsonb, 'a holds "sun"; joined with "flower" it makes sunflower.', '{"c":"a is a variable, so its value \"sun\" is used.","a":"+ adds no space between the two strings."}'::jsonb, null),
  ('pri-code-007', '"a"'::jsonb, '10 take away 4 is 6.', '{"b":"The - sign subtracts; it does not join numbers.","c":"Without quotes, the sum is worked out."}'::jsonb, null),
  ('pri-code-008', '{"accept":["Go!!"]}'::jsonb, 'All three strings are joined: Go!!', null, null),
  ('pri-code-009', '"b"'::jsonb, 'name holds "Ali", so the message is Hi Ali.', '{"c":"name has no quotes, so its value \"Ali\" is used.","a":"The + joins the strings; it is not printed."}'::jsonb, null),
  ('pri-code-010', '"false"'::jsonb, 'With quote marks, "5" is text. Joining two texts gives 55.', '{"true":"They are strings, so + joins them into 55 instead of adding."}'::jsonb, null),
  ('pri-code-011', '"c"'::jsonb, '"3" and "4" are strings; + joins them into 34.', '{"a":"The quotes make them text, so + joins rather than adds.","b":"The expression is worked out before printing."}'::jsonb, null),
  ('pri-code-012', '["c","a","b"]'::jsonb, 'Programs run from top to bottom, so the lines must be in the order you want the words.', null, null),
  ('pri-code-013', '"a"'::jsonb, 'n starts at 5 and becomes 6 before it is printed.', '{"b":"The second line changes n to 5 + 1.","c":"The program prints the value of n, not the text of a sum."}'::jsonb, null),
  ('pri-code-014', '{"accept":["6"]}'::jsonb, 'x * y is 2 * 3, which is 6.', null, null),
  ('pri-code-015', '"true"'::jsonb, '10 is greater than 3, so the comparison is true.', '{"false":"10 > 3 is a true statement, so JavaScript prints true."}'::jsonb, null),
  ('lsec-code-001', '"a"'::jsonb, '12 >= 13 is False, so the else branch prints child.', '{"b":"12 is not 13 or more, so the if part is skipped.","c":"Only one branch of an if/else runs."}'::jsonb, null),
  ('lsec-code-002', '"c"'::jsonb, '30 > 25 is true, so it prints hot.', '{"a":"30 is greater than 25, so the first branch runs.","b":"Only one branch of an if/else runs."}'::jsonb, null),
  ('lsec-code-003', '"b"'::jsonb, 'range(4) is 0, 1, 2, 3, and 0 + 1 + 2 + 3 = 6.', '{"c":"range(4) gives 0, 1, 2, 3, not 1 to 4.","a":"The loop adds the numbers, it does not count them."}'::jsonb, null),
  ('lsec-code-004', '"a"'::jsonb, 'len() counts the characters: Melaka has 6.', '{"b":"Count every letter: M-e-l-a-k-a is six.","c":"len() counts the letters only, not the quote marks."}'::jsonb, null),
  ('lsec-code-005', '"c"'::jsonb, '.length counts the characters: Penang has 6.', '{"a":"Count every letter: P-e-n-a-n-g is six.","b":".length counts the characters only, not the quote marks."}'::jsonb, null),
  ('lsec-code-006', '{"accept":["2"]}'::jsonb, '17 divided by 5 is 3 remainder 2, and % gives the remainder.', null, null),
  ('lsec-code-007', '{"accept":["2"]}'::jsonb, '17 divided by 5 is 3 remainder 2, and % gives the remainder.', null, null),
  ('lsec-code-008', '"true"'::jsonb, '3 and 3.0 have the same value, so == is True.', '{"false":"Python compares the values, and 3 equals 3.0."}'::jsonb, null),
  ('lsec-code-009', '"b"'::jsonb, 'The loop adds 1 + 2 + 3, so s is 6.', '{"c":"The loop adds 1, 2 and 3; it does not just count to 3.","a":"s holds numbers, so += adds rather than joins."}'::jsonb, null),
  ('lsec-code-010', '"a"'::jsonb, 'x += 3 means x = x + 3, so x becomes 8.', '{"b":"+= changes x to x + 3.","c":"x holds a number, so += adds."}'::jsonb, null),
  ('lsec-code-011', '"c"'::jsonb, '.upper() gives the string in capital letters.', '{"a":"print() shows the text without the quote marks.","b":"The method is run; its result is printed, not the code."}'::jsonb, null),
  ('lsec-code-012', '"b"'::jsonb, '.toUpperCase() gives the string in capitals.', '{"c":"console.log shows the text without the quote marks.","a":"The method is run; its result is printed, not the code."}'::jsonb, null),
  ('lsec-code-013', '["c","a","b"]'::jsonb, 'Variables must be given values before they are used, so the print line goes last.', null, null),
  ('lsec-code-014', '"false"'::jsonb, '=== also compares the type: the number 5 is not the string "5", so it prints false.', '{"true":"=== checks both value and type; a number and a string are different types."}'::jsonb, null),
  ('lsec-code-015', '"b"'::jsonb, '7 % 2 is 1, so the test is False and it prints odd.', '{"c":"7 % 2 is 1, not 0.","a":"The program prints a word chosen by the if, not the remainder."}'::jsonb, null),
  ('usec-code-001', '"a"'::jsonb, 'List positions start at 0, so nums[1] is 4.', '{"b":"Positions start at 0, so nums[1] is the second item.","c":"nums[1] is the second item, not the last."}'::jsonb, null),
  ('usec-code-002', '"c"'::jsonb, 'a.length - 1 is 2, the last position, which holds 6.', '{"a":"a.length is 3, but the code uses it to find the last item.","b":"a.length - 1 is 2, the position of the last item."}'::jsonb, null),
  ('usec-code-003', '"b"'::jsonb, 'double(5) returns 5 * 2 = 10.', '{"c":"The function returns x * 2, not x.","a":"The returned value is worked out before printing."}'::jsonb, null),
  ('usec-code-004', '"a"'::jsonb, 'sq(4) returns 4 * 4 = 16.', '{"b":"n * n multiplies 4 by itself, it does not double it.","c":"n holds a number, so * multiplies."}'::jsonb, null),
  ('usec-code-005', '"c"'::jsonb, '[0:4] takes positions 0, 1, 2 and 3: c, o, m, p.', '{"a":"The end position 4 is not included.","b":"Positions start at 0, so position 0 is the c."}'::jsonb, null),
  ('usec-code-006', '"b"'::jsonb, 'slice(0, 4) takes positions 0 to 3: comp.', '{"c":"The end position 4 is not included.","a":"Positions start at 0, so position 0 is the c."}'::jsonb, null),
  ('usec-code-007', '"a"'::jsonb, 'i doubles until it is no longer below 20: 1, 2, 4, 8, 16, 32.', '{"b":"The loop runs once more because 16 < 20.","c":"i only ever doubles: 1, 2, 4, 8, 16, 32."}'::jsonb, null),
  ('usec-code-008', '"true"'::jsonb, 'append adds one item, so the list has 4 items.', '{"false":"append adds 4 to the end, making four items."}'::jsonb, null),
