  ('preu-code-003', '"b"'::jsonb, 'range(4) gives 0 to 3, and squaring them gives [0, 1, 4, 9].', '{"c":"range(4) starts at 0, not 1.","a":"Each n is squared before it goes in the list."}'::jsonb, null),
  ('preu-code-004', '"a"'::jsonb, 'map multiplies each item by 10, and join puts commas between them.', '{"b":"map replaces every item with n * 10.","c":"map builds a new array; it does not add the items."}'::jsonb, null),
  ('preu-code-005', '"c"'::jsonb, 'f(4) = 4 * 3 * 2 * 1 = 24 (a factorial).', '{"a":"f multiplies, it does not add: 4 * 3 * 2 * 1.","b":"f calls itself until n is 1, multiplying as it goes."}'::jsonb, null),
